    steps: {
      prep: 'ஆழமாக உழுது, வடிகாலுக்காக 60 செ.மீ இடைவெளியில் பார் மற்றும் சால் அமைக்கவும்.',
      sow: 'பாரின் பக்கவாட்டில் குழிக்கு 1–2 விதைகளை 4–5 செ.மீ ஆழத்தில் ஊன்றவும். விதைத்த 15 நாட்களில் குழிக்கு ஒரு செடி விட்டு கலைக்கவும்.',
      water: 'விதைத்தவுடன் பாசனம் செய்து, 4-ஆம் நாள் உயிர்த் தண்ணீர் கொடுத்து, பின்னர் சுமார் 10–12 நாட்களுக்கு ஒருமுறை பாசனம் செய்யவும். விதைத்த 45–65 நாட்களில் (ஆண் பூ மற்றும் பட்டு வரும் பருவம்) தண்ணீர் பற்றாக்குறை கூடாது.',
      feed: 'ஏக்கருக்கு 5 டன் தொழு உரம் இடவும். ஒவ்வொரு 15 நாட்களுக்கும் ஜீவாமிர்தம் கொடுத்து, 30 நாட்களில் மண் அணைக்கவும்.',
      weed: '30 நாட்களில் கொத்தி, கையால் களையெடுத்து செடிகளுக்கு மண் அணைக்கவும்; 45 நாட்கள் வரை வயலில் களை இல்லாமல் வைக்கவும்.',
      harvest: 'கதிர் உறை காய்ந்து காகிதம் போல் ஆகி, மணிகள் கடினமாகும்போது அறுவடை செய்யவும். மணிகளை உதிர்ப்பதற்கு முன் கதிர்களை உலர்த்தவும்.' },
    pests: [
      ['படைப்புழு', 'மணல் மற்றும் சுண்ணாம்பு (9:1) கலவையை குருத்தில் இடவும்; கண்காணிப்புக்கு ஏக்கருக்கு 5 இனக்கவர்ச்சிப் பொறிகள் வைக்கவும் (மொத்தமாகப் பிடிக்க ஏக்கருக்கு 15); வேப்பங்கொட்டைச் சாறு 5% தெளிக்கவும்.'],
      ['தண்டுத் துளைப்பான்', 'காய்ந்த குருத்துகளை அகற்றவும்; டிரைக்கோகிரம்மா விடவும்; நீமாஸ்திரம் பயன்படுத்தவும்.'] ],
